// Make text safe to put inside an HTML email
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => n == null || n === '' ? '-' : '$' + Math.round(Number(n)).toLocaleString('en-US');

function trackingLink(carrier, number) {
  const n = encodeURIComponent(number);
  if (carrier === 'DHL') return `https://www.dhl.com/global-en/home/tracking/tracking-express.html?submit=1&tracking-id=${n}`;
  if (carrier === 'FedEx') return `https://www.fedex.com/fedextrack/?trknbr=${n}`;
  if (carrier === 'UPS') return `https://www.ups.com/track?tracknum=${n}`;
  return '';
}

const d = $json;
const link = trackingLink(d.carrier, d.tracking_number);
return {
  json: {
    ...d,
    subject: `Your ${d.brand} ${d.reference} is on its way`,
    html: `<p>Dear ${esc(d.name || 'customer')},</p>
<p>Thank you for your purchase. Your ${esc(d.brand)} ${esc(d.model)} ${esc(d.reference)} has been shipped with ${esc(d.carrier)}.</p>
<p>Tracking number: <b>${esc(d.tracking_number)}</b>${link ? ` - <a href="${link}">track your parcel</a>` : ''}</p>
<p>The parcel is insured and needs a signature on delivery. Import duties and taxes may apply in your country.</p>
<p>${esc(d.business_name)}</p>`,
  },
};

// Compare the DHL status with the one in our database. Only changes continue.
const shipments = $('Open DHL shipments').all();
const changed = [];
$input.all().forEach((item, i) => {
  const index = item.pairedItem?.item ?? i;
  const s = shipments[index]?.json;
  const status = item.json.shipments?.[0]?.status;
  if (!s || !status?.statusCode) return;
  if (status.statusCode === s.status) return;
  changed.push({
    json: { ...s, new_status: status.statusCode, detail: status.description || status.status || '' },
    pairedItem: { item: index },
  });
});
return changed;

// Make text safe to put inside an HTML email
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => n == null || n === '' ? '-' : '$' + Math.round(Number(n)).toLocaleString('en-US');

const d = $('Keep changed statuses').item.json;
const words = { 'pre-transit': 'is being prepared', transit: 'is on its way', delivered: 'has been delivered', failure: 'has a delivery problem' };
return {
  json: {
    ...d,
    subject: `Your ${d.brand} ${d.reference} ${words[d.new_status] || 'has a new status'}`,
    html: `<p>Dear ${esc(d.name || 'customer')},</p>
<p>Update for your ${esc(d.brand)} ${esc(d.reference)} (DHL ${esc(d.tracking_number)}): <b>${esc(d.detail || d.new_status)}</b>.</p>
<p>${esc(d.business_name)}</p>`,
  },
};

// When the database query finds nothing, n8n still passes one item: {"success": true}.
// Remove it so the next steps only run for real rows.
return $input.all()
  .map((item, index) => ({ json: item.json, pairedItem: { item: index } }))
  .filter(item => !(Object.keys(item.json).length === 1 && item.json.success === true));
